'use strict';const AlbumCommentsModalHead=({metadata:a})=>`
    <div class="modal fade" id="propalbumphotocomment${a.id}" tabindex="-1" role="dialog" aria-labelledby="label${a.id}" aria-hidden="true">
        <div class="modal-dialog modal-lg modal-dialog-scrollable" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title" id="commentModalLabel">
                        <div id="propalbumphotocomment${a.id}">
                            <img loading="lazy" src="${encodeURI(a.thumbnailUrlCentered)}" width="100" height="100" onError="Util.errorImg(this,\\'${a.title}\\',100)">
                        </div>Comments for ${a.fileName}
                    </h5>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                </div>
                <div class="modal-body">
                    <input type="hidden" id="currentCommentId${a.id}" name="currentCommentId${a.id}">
                    <ul class="list-group" id="commentList${a.id}">
`,AlbumComment=({commentId:a,commentText:b,userId:c,commentUserId:d,username:e})=>`
    <li class="list-group-item${d===c?" list-group-item-secondary":""}" id="comment${a}">
        <span id="commentcontainer${a}">
            <p id="commentcontent${a}">${b}</p>
            ${d===c?`<small>${e}<span style="float: right"><a href="#" id="deletecomment${a}"><span class="bi-trash"></span></a>&nbsp;&nbsp;<a href="#" id="editcomment${a}"><span class="bi-pencil"></span></a></span></small>`:""}
        </span>
        <span id="textareacontainer${a}"></span>
    </li>
`,AlbumCommentsModalFooter=({metadata:a})=>`
                    </ul>
                </div>
                <div class="modal-footer">
                    <textarea class="form-control" id="commentText${a.id}" rows="2"></textarea>
                    <button type="button" class="btn btn-primary" id="saveCommentMetadata${a.id}">Save</button>
                    <button type="button" class="btn btn-primary" id="updateCommentMetadata${a.id}">Update</button>
                    <button type="button" class="btn btn-secondary" id="dismissModalCommentMetadata${a.id}" data-bs-dismiss="modal">Cancel</button>
                    <button type="button" class="btn btn-secondary" id="cancelEditCommentMetadata${a.id}" data-bs-dismiss="modal">Cancel</button>
                </div>
            </div>
        </div>
    </div>
`,PersonModalHead=({metadata:a,recognitionLabels:b,taggedPeopleList:c})=>`
    <div class="modal fade" id="propperson${a.id}" tabindex="-1" role="dialog" aria-labelledby="label${a.id}" aria-hidden="true">
        <div class="modal-dialog modal-dialog-scrollable modal-lg" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title" id="exampleModalLabel">Edit "${a.title}"
                        <div id="proppersonThumbnail${a.id}">
                            <img loading="lazy" src="${encodeURI(a.thumbnailUrlCentered)}" width="100" height="100" onError="Util.errorImg(this,\'${a.title}\',100)">
                        </div>
                    </h5>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                </div>
                <div class="modal-body">
                    <form th:id="saveData${a.id}">
                        <input type="hidden" name="id" value="${a.id}">
                        <div class="form-group row">
                            <div class="col-sm">
                                <label for="tagpeople${a.id}" class="col-form-label">Tag People (comma separated)</label>
                                <div class="input-group" id="batchLabelIds${a.id}">
                                    <input type="text" class="form-control" aria-label="Tag People" id="tagpeople${a.id}" name="tagpeople" value="${c}">
                                    ${0<b.length?`
                                    <div class="input-group-append">
                                        <button class="btn btn-outline-secondary dropdown-toggle" id="tagpeopledropdown${a.id}" type="button" aria-haspopup="true" aria-expanded="false">People</button>
                                        <div class="dropdown-menu personDropdown" id="recognitionLabelsList${a.id}">
                                    `:""}
`,PersonModalDropDown=({metadata:a,recognitionLabel:b,checkedString:c})=>`
                                            <button class="dropdown-item" type="button">
                                                <input type="checkbox" class="recognitionLabel" value="${b.name}" name="recognitionLabel${a.id}[]" id="${a.id}-${b.name}"${c}>
                                                <label for="${a.id}-${b.name}" id="label-${a.id}-${b.name}">${b.name}</label>
                                            </button>
`,PersonModalFooter=({metadata:a,recognitionLabels:b})=>`
                                    ${0<b.length?"\n                                        </div>\n                                    </div>\n                                    ":""}
                                </div>
                            </div>
                        </div>
                        <div class="form-group row">
                            <div class="col-sm">
                                <input type="checkbox" name="isobject${a.id}" id="isobject${a.id}">
                                <label class="form-check-label" for="isobject${a.id}">This is not a person</label>
                            </div>
                        </div>
                    </form>
                    <div class="col-sm">
                        <span id="msg${a.id}"></span>
                    </div>
                </div>
                <div class="modal-footer">
                    <div id="personModalStatus${a.id}" class="spinner-grow me-auto" style="visibility: hidden;font-size: 2rem;" role="status" aria-hidden="true" data-bs-toggle="tooltip" data-bs-placement="right" title=""></div>
                    <button type="button" class="btn btn-primary" id="saveMetadata${a.id}">Save</button>
                    <button id="personModalCancel${a.id}" type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button>
                </div>
            </div>
        </div>
    </div>
`;

